def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    sr=sc=None
    for i in range(h):
        for j in range(w):
            if g[i][j]==3: sr,sc=i,j
    r,c=sr,sc
    dirs=[(-1,0),(0,1),(1,0),(0,-1)]
    L=2; exited=False; blocked=False; k=0
    for k in range(40):
        dr,dc=dirs[k%4]
        blocked=False; exited=False
        for _ in range(L):
            nr,nc=r+dr,c+dc
            if not(0<=nr<h and 0<=nc<w):
                exited=True; break
            if g[nr][nc]==2:
                blocked=True; break
            r,c=nr,nc; out[r][c]=3
        if blocked or exited: break
        if k%2==1: L+=2
    if exited:
        side=k%4
        if side==0: out[h-1][:]=[3]*w
        elif side==1:
            for i in range(h): out[i][w-1]=3
        elif side==2: out[0][:]=[3]*w
        else:
            for i in range(h): out[i][0]=3
    return out

